### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

const int MAXA = 200005;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    // f[v] 存储 v 的质因数分解 (质数, 指数)
    vector<unordered_map<int, int>> f(MAXA);
    vector<bool> is_prime(MAXA, true);

    // 类似埃氏筛预处理每个数的分解
    for (int i = 2; i < MAXA; i++) {
        if (!is_prime[i]) continue;
        f[i][i] = 1;
        for (int j = i + i; j < MAXA; j += i) {
            is_prime[j] = false;
            // 递推：检查 j/i 是否含有质数 i
            if (f[j / i].count(i)) {
                f[j][i] = f[j / i][i] + 1;
            } else {
                f[j][i] = 1;
            }
        }
    }

    unordered_map<int, int> now_f;
    long long now_val = 1;
    long long ans = 0;
    int i = 0;

    for (int j = 0; j < n; j++) {
        // 加入右端点
        for (auto &entry : f[a[j]]) {
            int p = entry.first;
            int e = entry.second;
            int &cnt = now_f[p];
            now_val /= (cnt + 1);
            cnt += e;
            now_val *= (cnt + 1);
        }

        // 收缩左端点
        while (now_val >= k && i <= j) {
            for (auto &entry : f[a[i]]) {
                int p = entry.first;
                int e = entry.second;
                int &cnt = now_f[p];
                now_val /= (cnt + 1);
                cnt -= e;
                if (cnt == 0) {
                    now_f.erase(p);
                }
                now_val *= (cnt + 1);
            }
            i++;
        }

        ans += i;
    }

    cout << ans << "\n";
    return 0;
}
